/* The UI icons (docs/STYLES.md 5.10) in one GPU texture.
 *
 * The masks come from icons_data.c, generated by gen_icons.py. icons_init
 * packs them, white with their alpha, into a small atlas; draw them with
 * ui_icon (draw.h), which tints them. Main thread only. */
#ifndef ICONS_H
#define ICONS_H

#include "icons_data.h"

#include <citro2d.h>

#include <stdbool.h>

/* After ui_init. Without linear memory for the atlas the app still runs:
 * icon_image then returns an image with no texture and nothing is drawn. */
bool icons_init(void);
void icons_exit(void);
C2D_Image icon_image(icon_id id);

#endif
